?><!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>comesy Editor · Cikkek</title><link rel="stylesheet" href="/assets/ui.css"><script src="/assets/ui.js" defer></script><style>body{font-family:system-ui;margin:0}.wrap{max-width:1100px;margin:auto;padding:24px}.head{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}.btn{background:#315fd6;color:white;padding:12px 17px;border-radius:8px}.card{padding:24px;margin-top:20px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:13px;border-bottom:1px solid var(--line)}@media(max-width:600px){.wrap{padding:14px}th:nth-child(3),td:nth-child(3){display:none}}</style></head><body><?php require __DIR__.'/app/header.php'; ?><main class="wrap"><a href="/">← Admin</a><div class="head"><h1>comesy Editor</h1><a class="btn" href="/editor.php">+ Új cikk</a></div><?php if($error):?><p><?=h($error)?></p><?php endif;?><div class="card"><table><thead><tr><th>Cím</th><th>Webhely</th><th>Státusz</th><th>Utolsó módosítás</th></tr></thead><tbody><?php foreach($articles as $a):?><tr><td><a href="/editor.php?id=<?=(int)$a['id']?>"><?=h($a['title'])?></a></td><td><?=h($a['site'])?></td><td><?=h($a['status'])?></td><td><?=h($a['updated_at'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$articles):?><p>Még nincs mentett cikk.</p><?php endif;?></div></main></body></html>
